with filtered as (select *, substring(full_name, 1, 3) as full_name_prefix from employees where email is not null) select date_trunc('year', hire_date) as year_start, count(*) as cnt, approx_percentile(salary, 0.95) as salary_p95, stddev_samp(salary) as salary_stddev, count(*) as event_count, round(avg(salary), 2) as avg_salary, size(collect_set(level)) as num_levels from filtered group by year_start order by event_count desc;
